package li.cil.oc.server.component;

import net.minecraft.nbt.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Original lossless {type,value} NBT tables, extended with the modern long-array tag. */
final class DebugNbt {
    private DebugNbt(){}
    static Map<String,Object> table(Tag tag){Object value;if(tag instanceof NumericTag number)value=number.getAsNumber();else if(tag instanceof ByteArrayTag bytes)value=bytes.getAsByteArray();else if(tag instanceof IntArrayTag ints)value=ints.getAsIntArray();else if(tag instanceof LongArrayTag longs)value=longs.getAsLongArray();else if(tag instanceof StringTag string)value=string.getAsString();else if(tag instanceof ListTag list){Object[] values=new Object[list.size()];for(int i=0;i<values.length;i++)values[i]=table(list.get(i));value=values;}else if(tag instanceof CompoundTag compound){Map<String,Object> values=new LinkedHashMap<>();for(String key:compound.getAllKeys())values.put(key,table(compound.get(key)));value=values;}else throw new IllegalArgumentException("invalid NBT tag");return Map.of("type",tag.getId(),"value",value);}
    private static String text(Object value){return value instanceof byte[] bytes?new String(bytes,StandardCharsets.UTF_8):String.valueOf(value);}
    private static Object field(Map<?,?> map,String key){Object value=map.get(key);if(value!=null)return value;for(var entry:map.entrySet())if(text(entry.getKey()).equals(key))return entry.getValue();return null;}
    private static Number number(Object value){if(value instanceof Number number)return number;throw new IllegalArgumentException("illegal or missing NBT value");}
    private static List<?> list(Object value){if(value instanceof byte[] bytes){List<Byte> values=new ArrayList<>();for(byte entry:bytes)values.add(entry);return values;}if(value instanceof int[] ints)return Arrays.stream(ints).boxed().toList();if(value instanceof long[] longs)return Arrays.stream(longs).boxed().toList();if(value instanceof Object[] array)return Arrays.asList(array);if(value instanceof Map<?,?> map)return map.entrySet().stream().filter(entry->entry.getKey() instanceof Number).sorted(Comparator.comparingInt(entry->((Number)entry.getKey()).intValue())).map(Map.Entry::getValue).toList();if(value instanceof String string)return list(string.getBytes(StandardCharsets.UTF_8));throw new IllegalArgumentException("illegal NBT list value");}
    static Tag tag(Map<?,?> table){int type=number(field(table,"type")).intValue();Object value=field(table,"value");return switch(type){case Tag.TAG_BYTE->ByteTag.valueOf(number(value).byteValue());case Tag.TAG_SHORT->ShortTag.valueOf(number(value).shortValue());case Tag.TAG_INT->IntTag.valueOf(number(value).intValue());case Tag.TAG_LONG->LongTag.valueOf(number(value).longValue());case Tag.TAG_FLOAT->FloatTag.valueOf(number(value).floatValue());case Tag.TAG_DOUBLE->DoubleTag.valueOf(number(value).doubleValue());case Tag.TAG_STRING->StringTag.valueOf(value instanceof byte[] bytes?new String(bytes,StandardCharsets.UTF_8):Objects.toString(value));case Tag.TAG_BYTE_ARRAY->{List<?> list=list(value);byte[] bytes=new byte[list.size()];for(int i=0;i<bytes.length;i++)bytes[i]=number(list.get(i)).byteValue();yield new ByteArrayTag(bytes);}case Tag.TAG_INT_ARRAY->new IntArrayTag(list(value).stream().mapToInt(entry->number(entry).intValue()).toArray());case Tag.TAG_LONG_ARRAY->new LongArrayTag(list(value).stream().mapToLong(entry->number(entry).longValue()).toArray());case Tag.TAG_LIST->{ListTag list=new ListTag();for(Object entry:list(value)){if(!(entry instanceof Map<?,?> map))throw new IllegalArgumentException("typed NBT table expected");if(!list.add(tag(map)))throw new IllegalArgumentException("incompatible NBT list entry");}yield list;}case Tag.TAG_COMPOUND->{if(!(value instanceof Map<?,?> map))throw new IllegalArgumentException("NBT compound table expected");CompoundTag compound=new CompoundTag();map.forEach((key,entry)->{if(!(entry instanceof Map<?,?> typed))throw new IllegalArgumentException("typed NBT table expected");compound.put(text(key),tag(typed));});yield compound;}default->throw new IllegalArgumentException("unsupported NBT type "+type);};}
}
